# ── 15 ──────────────────────────────────────────────────────────────────
stage "Device test — the M3 exit criterion"
say "One pass, end to end, on a free household."
check "quota shows a price" "A free household adding a second child hits the quota and sees a price."
check "webhook flips entitlement" "A sandbox purchase flips the household to premium via the webhook."
check "custom reward" "A custom reward can be added and redeemed."
check "payout drops coins" "A payout is recorded and the child's coins drop."
check "history past 7 days" "The grid scrolls past 7 days."
check "photo chore pays" "A photo chore is completed, approved, and pays."
pause

# ── 16 ──────────────────────────────────────────────────────────────────
stage "Report back to issue #$ISSUE"
say "Posting the hand-test results as a comment."
if (( ${#RESULTS[@]} == 0 )); then
  warn "No hand-test results recorded — nothing to report."
  SKIPPED+=("the hand-test comment on issue #$ISSUE")
  finish
  exit 0
fi
comment=$(printf '## Hand-test results\n\nRun via `scripts/setup-premium.sh` on %s.\n\n%s\n' \
  "$(date -u '+%Y-%m-%d %H:%M UTC')" "$(printf '%s\n' "${RESULTS[@]}")")
printf '\n%s\n\n' "$comment"
if confirm "Post this to issue #$ISSUE?"; then
  if printf '%s' "$comment" | gh issue comment "$ISSUE" --body-file - >/dev/null 2>&1; then
    printf '  %s✓ posted%s to issue #%s\n' "$GREEN" "$RESET" "$ISSUE"
  else
    warn "gh could not post — copy the comment above onto the issue by hand."
    SKIPPED+=("the hand-test comment on issue #$ISSUE")
  fi
else
  SKIPPED+=("the hand-test comment on issue #$ISSUE")
fi
pause

finish
